use std::ops::RangeInclusive;

use serde_json::{Map, Value};

use crate::error::{Error, Result};

/// A view of a command's members in which `null` counts as absent.
#[derive(Clone, Copy)]
pub struct Params<'a>(&'a Map<String, Value>);

impl<'a> Params<'a> {
    pub fn new(members: &'a Map<String, Value>) -> Self {
        Self(members)
    }

    pub fn get(self, name: &str) -> Option<&'a Value> {
        self.0.get(name).filter(|value| !value.is_null())
    }

    /// Fails on the first of `names` that is absent.
    pub fn require(self, names: &[&str]) -> Result<()> {
        match names.iter().find(|name| self.get(name).is_none()) {
            Some(name) => Err(Error::missing(name)),
            None => Ok(()),
        }
    }

    pub fn string(self, name: &str) -> Result<Option<&'a str>> {
        self.get(name)
            .map(|value| {
                value.as_str().ok_or_else(|| Error::invalid(format!("{name} must be a string")))
            })
            .transpose()
    }

    /// A string accepted by `valid`; `rule` describes it in the error message.
    pub fn string_where(
        self,
        name: &str,
        valid: impl Fn(&str) -> bool,
        rule: &str,
    ) -> Result<Option<&'a str>> {
        match self.string(name)? {
            Some(text) if !valid(text) => Err(Error::invalid(format!("{name} must be {rule}"))),
            other => Ok(other),
        }
    }

    pub fn text(self, name: &str) -> Result<&'a str> {
        self.string(name)?.ok_or_else(|| Error::missing(name))
    }

    pub fn integer(self, name: &str, range: RangeInclusive<u64>) -> Result<Option<u64>> {
        self.get(name)
            .map(|value| match value.as_u64() {
                Some(n) if range.contains(&n) => Ok(n),
                _ => Err(Error::invalid(format!(
                    "{name} must be an integer from {} to {}",
                    range.start(),
                    range.end()
                ))),
            })
            .transpose()
    }

    pub fn required_integer(self, name: &str, range: RangeInclusive<u64>) -> Result<u64> {
        self.integer(name, range)?.ok_or_else(|| Error::missing(name))
    }

    pub fn boolean(self, name: &str) -> Result<Option<bool>> {
        self.get(name)
            .map(|value| {
                value.as_bool().ok_or_else(|| Error::invalid(format!("{name} must be a boolean")))
            })
            .transpose()
    }
}
