use serde_json::Value;

use crate::error::{Error, Result};
use crate::params::Params;

/// Whole seconds, used for the virtual clock and every duration.
pub type Seconds = u64;

pub const VISIBILITY_TIMEOUT_MAX: Seconds = 43_200;
pub const DELAY_MAX: Seconds = 900;

const ATTRIBUTE_NAMES: [&str; 7] = [
    "VisibilityTimeout",
    "DelaySeconds",
    "RetentionSeconds",
    "Fifo",
    "ContentBasedDeduplication",
    "DeadLetterQueue",
    "MaxReceiveCount",
];

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: String,
    pub max_receive_count: u64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Attributes {
    pub visibility_timeout: Seconds,
    pub delay: Seconds,
    pub retention: Seconds,
    pub fifo: bool,
    pub content_based_deduplication: bool,
    pub dead_letter: Option<DeadLetter>,
}

impl Default for Attributes {
    fn default() -> Self {
        Self {
            visibility_timeout: 30,
            delay: 0,
            retention: 345_600,
            fifo: false,
            content_based_deduplication: false,
            dead_letter: None,
        }
    }
}

impl Attributes {
    /// Overwrites the attributes that `update` carries. The caller has checked
    /// that the two dead-letter members come together.
    pub fn apply(&mut self, update: &AttributeUpdate) {
        self.visibility_timeout = update.visibility_timeout.unwrap_or(self.visibility_timeout);
        self.delay = update.delay.unwrap_or(self.delay);
        self.retention = update.retention.unwrap_or(self.retention);
        self.fifo = update.fifo.unwrap_or(self.fifo);
        self.content_based_deduplication =
            update.content_based_deduplication.unwrap_or(self.content_based_deduplication);
        if let (Some(queue), Some(max_receive_count)) =
            (&update.dead_letter_queue, update.max_receive_count)
        {
            self.dead_letter = Some(DeadLetter { queue: queue.clone(), max_receive_count });
        }
    }
}

/// The attributes present in a request, each checked on its own.
#[derive(Debug, Default)]
pub struct AttributeUpdate {
    pub visibility_timeout: Option<Seconds>,
    pub delay: Option<Seconds>,
    pub retention: Option<Seconds>,
    pub fifo: Option<bool>,
    pub content_based_deduplication: Option<bool>,
    pub dead_letter_queue: Option<String>,
    pub max_receive_count: Option<u64>,
}

impl AttributeUpdate {
    pub fn parse(value: &Value) -> Result<Self> {
        let Value::Object(members) = value else {
            return Err(Error::invalid("Attributes must be an object"));
        };
        if let Some(name) = members.keys().find(|key| !ATTRIBUTE_NAMES.contains(&key.as_str())) {
            return Err(Error::invalid(format!("unknown attribute {name}")));
        }
        let p = Params::new(members);
        Ok(Self {
            visibility_timeout: p.integer("VisibilityTimeout", 0..=VISIBILITY_TIMEOUT_MAX)?,
            delay: p.integer("DelaySeconds", 0..=DELAY_MAX)?,
            retention: p.integer("RetentionSeconds", 60..=1_209_600)?,
            fifo: p.boolean("Fifo")?,
            content_based_deduplication: p.boolean("ContentBasedDeduplication")?,
            dead_letter_queue: p.string("DeadLetterQueue")?.map(str::to_owned),
            max_receive_count: p.integer("MaxReceiveCount", 1..=1000)?,
        })
    }

    pub fn has_partial_dead_letter(&self) -> bool {
        self.dead_letter_queue.is_some() != self.max_receive_count.is_some()
    }
}
