cat > src/queue.rs <<'E'
use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};

use crate::attributes::{Attributes, Seconds};

/// A deduplication id stays in force for this many seconds after acceptance.
const DEDUP_WINDOW: Seconds = 300;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    Visible,
    InFlight,
    Delayed,
}

#[derive(Debug, Clone, Copy)]
enum Hold {
    Free,
    Delayed { until: Seconds },
    InFlight { until: Seconds },
}

impl Hold {
    fn state(self, now: Seconds) -> State {
        match self {
            Self::Delayed { until } if now < until => State::Delayed,
            Self::InFlight { until } if now < until => State::InFlight,
            _ => State::Visible,
        }
    }
}

#[derive(Debug)]
pub struct Message {
    pub id: u64,
    body: String,
    sent_at: Seconds,
    receive_count: u64,
    first_received_at: Option<Seconds>,
    group: Option<String>,
    hold: Hold,
    handle: Option<u64>,
}

impl Message {
    pub fn new(id: u64, body: String, sent_at: Seconds, group: Option<String>, delay: Seconds) -> Self {
        let hold = if delay > 0 { Hold::Delayed { until: sent_at + delay } } else { Hold::Free };
        Self { id, body, sent_at, receive_count: 0, first_received_at: None, group, hold, handle: None }
    }
}

#[derive(Debug, Clone, Copy)]
pub struct Accepted {
    at: Seconds,
    pub message_id: u64,
    pub sequence: u64,
}

impl Accepted {
    pub fn new(at: Seconds, message_id: u64, sequence: u64) -> Self {
        Self { at, message_id, sequence }
    }
}

#[derive(Debug)]
pub struct Delivered {
    pub id: u64,
    pub handle: u64,
    pub body: String,
    pub receive_count: u64,
    pub sent_at: Seconds,
    pub first_received_at: Seconds,
    pub group: Option<String>,
    /// Position in arrival order; it is the `SequenceNumber` of FIFO queues.
    pub sequence: u64,
}

#[derive(Debug, Default)]
pub struct Received {
    pub delivered: Vec<Delivered>,
    /// Messages that reached the receive limit, to be added to the dead-letter queue.
    pub dead: Vec<Message>,
}

#[derive(Debug, Default, PartialEq, Eq)]
pub struct Counts {
    pub visible: usize,
    pub in_flight: usize,
    pub delayed: usize,
}

#[derive(Debug)]
pub struct Queue {
    pub attributes: Attributes,
    /// Keyed by arrival number, which starts at 1 and never repeats.
    messages: BTreeMap<u64, Message>,
    /// `(sent_at, arrival)` of every message, so retention only looks at the oldest.
    by_age: BTreeSet<(Seconds, u64)>,
    /// Latest receipt handle of each delivered message, mapped to its arrival number.
    handles: HashMap<u64, u64>,
    next_arrival: u64,
    deduplication: HashMap<String, Accepted>,
}

impl Queue {
    pub fn new(attributes: Attributes) -> Self {
        Self {
            attributes,
            messages: BTreeMap::new(),
            by_age: BTreeSet::new(),
            handles: HashMap::new(),
            next_arrival: 1,
            deduplication: HashMap::new(),
        }
    }

    pub fn len(&self) -> usize {
        self.messages.len()
    }

    /// Removes messages whose retention has run out; call before reading the queue.
    pub fn expire(&mut self, now: Seconds) {
        while let Some(&(sent_at, arrival)) = self.by_age.first() {
            if now < sent_at + self.attributes.retention {
                break;
            }
            self.remove(arrival);
        }
    }

    /// Adds `message` at the end and returns its arrival number.
    pub fn push(&mut self, message: Message) -> u64 {
        let arrival = self.next_arrival;
        self.next_arrival += 1;
        self.by_age.insert((message.sent_at, arrival));
        self.messages.insert(arrival, message);
        arrival
    }

    /// Adds a message that came from another queue as if it were new, keeping
    /// its identity, body, send time and group.
    pub fn push_dead(&mut self, mut message: Message) {
        message.receive_count = 0;
        message.first_received_at = None;
        message.hold = Hold::Free;
        message.handle = None;
        self.push(message);
    }

    /// Removes the message at `arrival`, which must be present.
    pub fn remove(&mut self, arrival: u64) -> Message {
        let message = self.messages.remove(&arrival).expect("callers pass arrival numbers of held messages");
        self.by_age.remove(&(message.sent_at, arrival));
        if let Some(handle) = message.handle {
