    }

    pub fn set_in_flight_until(&mut self, arrival: u64, until: Seconds) {
        if let Some(message) = self.messages.get_mut(&arrival) {
            message.hold = Hold::InFlight { until };
        }
    }

    /// Delivers up to `max` messages. Messages at `dead_letter_limit` receives
    /// are handed back in `dead` instead and do not count toward `max`.
    pub fn receive(
        &mut self,
        now: Seconds,
        max: usize,
        visibility_timeout: Seconds,
        dead_letter_limit: Option<u64>,
        next_handle: &mut u64,
    ) -> Received {
