use std::collections::BTreeMap;

use serde_json::{json, Map, Value};

use crate::attributes::{AttributeUpdate, Attributes, Seconds, DELAY_MAX, VISIBILITY_TIMEOUT_MAX};
use crate::error::{Error, ErrorCode, Result};
use crate::params::Params;
use crate::queue::{Accepted, Message, Queue};

const MAX_QUEUES: usize = 1000;
const MAX_MESSAGES: usize = 100_000;

#[derive(Default)]
pub struct Service {
    now: Seconds,
    queues: BTreeMap<String, Queue>,
    /// Number of the next `MessageId`.
    next_message: u64,
    /// Number of the next `ReceiptHandle`.
    next_handle: u64,
}

fn valid_queue_name(name: &str) -> bool {
    let plain = |s: &str, max: usize| {
        (1..=max).contains(&s.len()) && s.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
    };
    match name.strip_suffix(".fifo") {
        Some(stem) => plain(stem, 75),
        None => plain(name, 80),
    }
}

fn valid_identifier(id: &str) -> bool {
    (1..=128).contains(&id.len()) && id.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

/// Finds a queue and drops its expired messages.
fn lookup<'a>(queues: &'a mut BTreeMap<String, Queue>, name: &str, now: Seconds) -> Result<&'a mut Queue> {
    let queue = queues
        .get_mut(name)
        .ok_or_else(|| Error::new(ErrorCode::QueueDoesNotExist, format!("no queue named {name}")))?;
    queue.expire(now);
    Ok(queue)
}

fn no_such_queue(name: &str) -> Error {
    Error::new(ErrorCode::QueueDoesNotExist, format!("no queue named {name}"))
}

impl Service {
    pub fn new() -> Self {
        Self { next_message: 1, next_handle: 1, ..Self::default() }
    }

    /// Runs one input line and returns the one-line JSON response.
    pub fn execute(&mut self, line: &[u8]) -> String {
        if self.next_message == 0 {
            *self = Self::new();
        }
        let response = match self.run(line) {
            Ok(mut result) => {
                result["ok"] = Value::Bool(true);
                result
            }
            Err(error) => json!({"ok": false, "error": {"code": error.code.as_str(), "message": error.message}}),
        };
        response.to_string()
    }

    fn run(&mut self, line: &[u8]) -> Result<Value> {
        let bad = |why: &str| Error::new(ErrorCode::InvalidRequest, why.to_owned());
        let text = std::str::from_utf8(line).map_err(|_| bad("line is not valid UTF-8"))?;
        let Ok(Value::Object(members)) = serde_json::from_str::<Value>(text) else {
            return Err(bad("line is not a JSON object"));
        };
        let p = Params::new(&members);
        let command = p.get("Command").and_then(Value::as_str).ok_or_else(|| bad("Command must be a string"))?;
        match command {
            "CreateQueue" => self.create_queue(p),
            "SetQueueAttributes" => self.set_queue_attributes(p),
            "GetQueueAttributes" => self.get_queue_attributes(p),
            "ListQueues" => self.list_queues(p),
            "DeleteQueue" => self.delete_queue(p),
            "PurgeQueue" => self.purge_queue(p),
            "Tick" => self.tick(p),
            "SendMessage" => self.send_message(p),
            "ReceiveMessage" => self.receive_message(p),
            "DeleteMessage" => self.delete_message(p),
            "ChangeMessageVisibility" => self.change_message_visibility(p),
            _ => Err(bad("unknown command")),
        }
    }

    fn create_queue(&mut self, p: Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        let name = p.text("QueueName")?;
        if !valid_queue_name(name) {
            return Err(Error::new(ErrorCode::QueueNameInvalid, format!("{name:?} is not a valid queue name")));
        }
        let update = match p.get("Attributes") {
            Some(_) => AttributeUpdate::parse(p.get("Attributes").expect("just checked"))?,
            None => AttributeUpdate::default(),
        };
        let mut attributes = Attributes::default();
        attributes.apply(&update);
        if name.ends_with(".fifo") != attributes.fifo {
            return Err(Error::new(ErrorCode::QueueNameInvalid, "the .fifo suffix and Fifo must agree"));
        }
        if attributes.content_based_deduplication && !attributes.fifo {
            return Err(Error::invalid("ContentBasedDeduplication needs a FIFO queue"));
        }
        if update.has_partial_dead_letter() {
            return Err(Error::invalid("DeadLetterQueue and MaxReceiveCount come together"));
        }
        if let Some(existing) = self.queues.get(name) {
            return if existing.attributes == attributes {
                Ok(json!({}))
            } else {
                Err(Error::new(ErrorCode::QueueAlreadyExists, format!("{name} exists with other attributes")))
            };
        }
        if let Some(dead) = &attributes.dead_letter {
            let target = self.queues.get(&dead.queue).ok_or_else(|| no_such_queue(&dead.queue))?;
            if target.attributes.fifo != attributes.fifo {
                return Err(Error::invalid("the dead-letter queue must be of the same type"));
            }
        }
        if self.queues.len() >= MAX_QUEUES {
            return Err(Error::new(ErrorCode::LimitExceeded, "too many queues"));
        }
        self.queues.insert(name.to_owned(), Queue::new(attributes));
        Ok(json!({}))
    }

    fn set_queue_attributes(&mut self, p: Params) -> Result<Value> {
        p.require(&["QueueName", "Attributes"])?;
        let name = p.text("QueueName")?;
        let update = AttributeUpdate::parse(p.get("Attributes").ok_or_else(|| Error::missing("Attributes"))?)?;
        let fifo = lookup(&mut self.queues, name, self.now)?.attributes.fifo;
        if update.fifo.is_some() {
            return Err(Error::new(ErrorCode::UnsupportedOperation, "the type of a queue cannot change"));
        }
        if update.content_based_deduplication == Some(true) && !fifo {
            return Err(Error::invalid("ContentBasedDeduplication needs a FIFO queue"));
        }
        if update.has_partial_dead_letter() {
            return Err(Error::invalid("DeadLetterQueue and MaxReceiveCount come together"));
        }
        if let Some(dead) = &update.dead_letter_queue {
            let target = self.queues.get(dead).ok_or_else(|| no_such_queue(dead))?;
            if dead == name || target.attributes.fifo != fifo {
                return Err(Error::invalid("unsuitable dead-letter queue"));
            }
        }
        lookup(&mut self.queues, name, self.now)?.attributes.apply(&update);
        Ok(json!({}))
    }

    fn get_queue_attributes(&mut self, p: Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        let queue = lookup(&mut self.queues, p.text("QueueName")?, self.now)?;
        let a = &queue.attributes;
        let mut attributes = json!({
            "VisibilityTimeout": a.visibility_timeout,
            "DelaySeconds": a.delay,
            "RetentionSeconds": a.retention,
            "Fifo": a.fifo,
            "ContentBasedDeduplication": a.content_based_deduplication,
        });
        if let Some(dead) = &a.dead_letter {
            attributes["DeadLetterQueue"] = json!(dead.queue);
            attributes["MaxReceiveCount"] = json!(dead.max_receive_count);
        }
        let counts = queue.counts(self.now);
        Ok(json!({
            "Attributes": attributes,
            "Counts": {"Visible": counts.visible, "InFlight": counts.in_flight, "Delayed": counts.delayed},
        }))
    }

    fn list_queues(&self, p: Params) -> Result<Value> {
        let prefix = p.string("Prefix")?.unwrap_or("");
        let names: Vec<&String> =
            self.queues.range(prefix.to_owned()..).map(|(name, _)| name).take_while(|n| n.starts_with(prefix)).collect();
        Ok(json!({"QueueNames": names}))
    }

    fn delete_queue(&mut self, p: Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        let name = p.text("QueueName")?;
        lookup(&mut self.queues, name, self.now)?;
        self.queues.remove(name);
        for queue in self.queues.values_mut() {
            if queue.attributes.dead_letter.as_ref().is_some_and(|dead| dead.queue == name) {
                queue.attributes.dead_letter = None;
            }
        }
        Ok(json!({}))
    }

    fn purge_queue(&mut self, p: Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        lookup(&mut self.queues, p.text("QueueName")?, self.now)?.purge();
        Ok(json!({}))
    }

    fn tick(&mut self, p: Params) -> Result<Value> {
        p.require(&["Seconds"])?;
        self.now += p.required_integer("Seconds", 0..=1_209_600)?;
        Ok(json!({"Now": self.now}))
    }

    fn send_message(&mut self, p: Params) -> Result<Value> {
        p.require(&["QueueName", "Body"])?;
        let name = p.text("QueueName")?;
        let body = p
            .string_where("Body", |b| (1..=1024).contains(&b.len()), "1 to 1024 bytes")?
            .ok_or_else(|| Error::missing("Body"))?;
        let delay = p.integer("DelaySeconds", 0..=DELAY_MAX)?;
        let rule = "1 to 128 characters of A-Z a-z 0-9 _ -";
        let group = p.string_where("GroupId", valid_identifier, rule)?;
        let deduplication = p.string_where("DeduplicationId", valid_identifier, rule)?;
        let now = self.now;
        let queue = lookup(&mut self.queues, name, now)?;
        let fifo = queue.attributes.fifo;
        if (!fifo && (group.is_some() || deduplication.is_some())) || (fifo && delay.is_some()) {
            return Err(Error::new(ErrorCode::UnsupportedOperation, "parameter not supported by this queue type"));
        }
        let mut dedup_id = None;
        if fifo {
            if group.is_none() {
                return Err(Error::missing("GroupId"));
            }
            let id = match deduplication {
                Some(id) => id,
                None if queue.attributes.content_based_deduplication => body,
                None => return Err(Error::missing("DeduplicationId")),
            };
            if let Some(original) = queue.duplicate(id, now) {
                return Ok(json!({
                    "MessageId": format!("m-{}", original.message_id),
                    "SequenceNumber": original.sequence,
                }));
            }
            dedup_id = Some(id);
        }
        if queue.len() >= MAX_MESSAGES {
            return Err(Error::new(ErrorCode::LimitExceeded, "queue is full"));
        }
        let id = self.next_message;
        self.next_message += 1;
        let delay = delay.unwrap_or(queue.attributes.delay);
        let sequence = queue.push(Message::new(id, body.to_owned(), now, group.map(str::to_owned), delay));
