            .delivered
            .into_iter()
            .map(|d| {
                let mut message = json!({
                    "MessageId": format!("m-{}", d.id),
                    "ReceiptHandle": format!("r-{}", d.handle),
                    "Body": d.body,
                    "ReceiveCount": d.receive_count,
                    "SentAt": d.sent_at,
                    "FirstReceivedAt": d.first_received_at,
                });
                if fifo {
                    message["GroupId"] = json!(d.group);
                    message["SequenceNumber"] = json!(d.sequence);
                }
                message
            })
            .collect();
        Ok(json!({"Messages": messages}))
    }

    /// Resolves a handle to the arrival number of the in-flight message it names.
    fn in_flight(&mut self, queue_name: &str, handle: &str) -> Result<(&mut Queue, u64)> {
